parameters.jsCode:
// Parse Groq response
const groqResponse = $json;
const content = groqResponse.choices?.[0]?.message?.content || '{}';

// Extract JSON from response
let parsed;
try {
  // Clean up common JSON formatting issues
  let cleanContent = content
    .replace(/```json\s*/gi, '')
    .replace(/```\s*/g, '')
    .trim();

  // Try to find JSON in the response
  const jsonMatch = cleanContent.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(jsonMatch ? jsonMatch[0] : cleanContent);
} catch (e) {
  // Fallback if JSON parsing fails
  parsed = {
    intent: 'GENERAL_INFO',
    confidence: 0.5,
    extracted_info: {},
    urgency: 'medium',
    suggested_response: 'Thank you for your email. We will get back to you shortly.'
  };
}

// Get webhook data for context
const webhookData = $('Email Webhook').item.json.body || {};

// Generate routing destination based on intent
const routingMap = {
  'VIEWING_REQUEST': 'viewings@agentloop.co.za',
  'PRICE_INQUIRY': 'sales@agentloop.co.za',
  'GENERAL_INFO': 'info@agentloop.co.za',
  'COMPLAINT': 'urgent@agentloop.co.za',
  'DOCUMENT_REQUEST': 'admin@agentloop.co.za',
  'SPAM': null
};

return {
  json: {
    email_id: webhookData.email_id || $execution.id || 'unknown',
    from_email: webhookData.from || 'unknown@example.com',
    subject: webhookData.subject || 'No Subject',
    email_body: webhookData.body || webhookData.text || '',
    intent: parsed.intent || 'GENERAL_INFO',
    confidence: parsed.confidence || 0.5,
    extracted_info: parsed.extracted_info || {},
    urgency: parsed.urgency || 'medium',
    suggested_response: parsed.suggested_response || 'Thank you for your email.',
    route_to: routingMap[parsed.intent] || 'info@agentloop.co.za',
    auto_respond: (parsed.confidence || 0) > 0.8 && parsed.intent !== 'COMPLAINT' && parsed.intent !== 'SPAM',
    classified_at: $now
  }
};

